contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        bytes32 role,
        bytes32 adminRole,
        address account,
        address target,
        uint256 value,
        bytes calldata data,
        bytes32 predecessor,
        bytes32 salt,
        uint256 delay
    ) public {
        require(true);

        bytes32 proposerRole = c.PROPOSER_ROLE();
        bytes32 executorRole = c.EXECUTOR_ROLE();
        bytes32 timelockAdminRole = c.TIMELOCK_ADMIN_ROLE();
        bytes32 defaultAdminRole = c.DEFAULT_ADMIN_ROLE();

        bool roleAdminIsStable = c.getRoleAdmin(timelockAdminRole) == timelockAdminRole;
        bool proposerAdminIsStable = c.getRoleAdmin(proposerRole) == timelockAdminRole;
        bool executorAdminIsStable = c.getRoleAdmin(executorRole) == timelockAdminRole;
        bool roleIsNotDefaultAdmin = role != defaultAdminRole;
        bool roleIsNotTimelockAdmin = role != timelockAdminRole;
        bool roleIsNotProposer = role != proposerRole;
        bool roleIsNotExecutor = role != executorRole;

        bool hasRoleBefore = c.hasRole(role, account);
        bool senderHasAdmin = c.hasRole(c.getRoleAdmin(role), address(this));
        bool senderIsProposer = c.hasRole(proposerRole, address(this));

        bytes32 operationId = c.hashOperation(target, value, data, predecessor, salt);
        bool isOperationBefore = c.isOperation(operationId);

        uint256 minDelay = c.getMinDelay();

        bool grantReverted;
        try c.grantRole(role, account) {
            grantReverted = false;
        } catch {
            grantReverted = true;
        }

        bool scheduleReverted;
        try c.schedule(target, value, data, predecessor, salt, delay) {
            scheduleReverted = false;
        } catch {
            scheduleReverted = true;
        }

        bool hasRoleAfter = c.hasRole(role, account);
        bool isOperationAfter = c.isOperation(operationId);

        assert(
            roleAdminIsStable &&
            proposerAdminIsStable &&
            executorAdminIsStable &&
            (!roleIsNotDefaultAdmin || hasRoleBefore == hasRoleAfter || senderHasAdmin) &&
            (grantReverted != senderHasAdmin) &&
            (scheduleReverted != (senderIsProposer && !isOperationBefore && delay >= minDelay)) &&
            (!isOperationAfter || senderIsProposer) &&
            (!isOperationAfter || !isOperationBefore || scheduleReverted) &&
            (!roleIsNotTimelockAdmin && !roleIsNotProposer && !roleIsNotExecutor || true)
        );
    }

    receive() external payable {}
}

