contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bytes32 role, address account) public {
        require(account != address(0), "account must be nonzero");

        // Ensure this test contract can administer the role. Using TIMELOCK_ADMIN_ROLE
        // as the admin target for the role being granted would be circular for arbitrary
        // roles, so instead we test the already-granted role that the constructor gave
        // this contract: it holds TIMELOCK_ADMIN_ROLE, and roles PROPOSER_ROLE and
        // EXECUTOR_ROLE are administered by TIMELOCK_ADMIN_ROLE.
        // For a general role, the only role the test contract certainly administers
        // without prior setup is TIMELOCK_ADMIN_ROLE itself (its admin is itself and
        // it holds it). However, role is an arbitrary parameter; to keep the property
        // general and reachable, restrict to roles whose admin is TIMELOCK_ADMIN_ROLE
        // by using the actual role's admin as reported by the contract, which for the
        // timelock-standard roles is TIMELOCK_ADMIN_ROLE.
        require(c.getRoleAdmin(role) == c.TIMELOCK_ADMIN_ROLE(), "test only has admin for timelock-administered roles");
        require(c.hasRole(c.TIMELOCK_ADMIN_ROLE(), address(this)), "test must hold the timelock admin role");

        bool reverted;
        try c.grantRole(role, account) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: because this contract holds the role's admin role, grantRole
        // must not revert, and the recipient must have the role afterwards.
        assert(!reverted && c.hasRole(role, account));
    }
}

