contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address target, uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt, uint256 delay, uint256 sendAmount) public payable {
        require(address(this).balance >= sendAmount, "insufficient balance");

        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);

        uint256 beforeTimestamp = c.getTimestamp(id);
        uint256 minDelay = c.getMinDelay();
        require(delay >= minDelay, "delay too small");
        require(sendAmount == value, "sendAmount must match operation value");

        c.schedule(target, value, data, predecessor, salt, delay);
        uint256 timestampAfterSchedule = c.getTimestamp(id);

        bool executedEarly = true;
        try c.execute{value: sendAmount}(target, value, data, predecessor, salt) {
            executedEarly = false;
        } catch {}

        bool executedNow = true;
        try c.execute{value: sendAmount}(target, value, data, predecessor, salt) {
            executedNow = false;
        } catch {}

        uint256 timestampAfterExecute = c.getTimestamp(id);
        uint256 contractBalanceAfter = address(c).balance;

        assert((timestampAfterSchedule > beforeTimestamp) && (timestampAfterSchedule == timestampAfterExecute) && executedEarly && (!executedNow || contractBalanceAfter == sendAmount));
    }

    receive() external payable {}
}

