        bytes32 id = c.hashOperation(target, 0, "", bytes32(0), salt);

        uint256 beforeCancel = c.getTimestamp(id);

        c.schedule(target, 0, "", bytes32(0), salt, delay);
        uint256 afterSchedule = c.getTimestamp(id);

        c.cancel(id);
        uint256 afterCancel = c.getTimestamp(id);

        bool cancelUnscheduledReverted;
        try c.cancel(bytes32(uint256(id) ^ 1)) {
            cancelUnscheduledReverted = false;
        } catch {
            cancelUnscheduledReverted = true;
        }

        assert(afterSchedule > block.timestamp && afterCancel == 0 && cancelUnscheduledReverted);
    }

